turns.content:
{"t":"say","text":"I'll design a fully serverless REST API using Function Compute and API Gateway, scaling to zero for spiky traffic."}
{"t":"req","text":"Pay only for what we use"}
{"t":"plan","products":["mobile-app","dns","cloud-native-api-gateway","fc","tablestore","oss","sls"]}
{"t":"assume","id":"region","text":"Singapore region","alt":"Another region"}
{"t":"assume","id":"auth","text":"API key or JWT auth on gateway","alt":"No auth"}
{"t":"group","id":"clients","kind":"external","label":"Clients","parent":null}
{"t":"node","id":"app","product":"mobile-app","label":"Mobile app","group":"clients","why":"End users calling the REST API."}
{"t":"node","id":"dns","product":"dns","label":"DNS","group":null,"why":"Resolves the API domain name."}
{"t":"edge","id":"e-app-dns","from":"app","to":"dns","kind":"resolve"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"API VPC","parent":"sg"}
{"t":"node","id":"gateway","product":"cloud-native-api-gateway","label":"API Gateway","group":"vpc","why":"Routes REST calls, handles auth and throttling."}
{"t":"edge","id":"e-app-gateway","from":"app","to":"gateway","label":"HTTPS"}
{"t":"node","id":"api","product":"fc","label":"API functions","group":"vpc","why":"Serverless compute that scales to zero on spikes."}
{"t":"edge","id":"e-gateway-api","from":"gateway","to":"api","label":"invoke"}
{"t":"node","id":"db","product":"tablestore","label":"Data store","group":"sg","why":"Serverless NoSQL storage billed per request."}
{"t":"edge","id":"e-api-db","from":"api","to":"db","label":"read/write"}
{"t":"node","id":"storage","product":"oss","label":"File storage","group":"sg","why":"Stores uploaded files with pay-per-use billing."}
{"t":"edge","id":"e-api-storage","from":"api","to":"storage","label":"objects"}
{"t":"node","id":"logs","product":"sls","label":"Logs","group":"sg","why":"Collects function logs for debugging and alerts."}
{"t":"edge","id":"e-api-logs","from":"api","to":"logs","kind":"control"}
{"t":"ask","id":"data-model","text":"What kind of data will the API store?","options":["User profiles and JSON docs","Time-series or IoT events","Relational rows with joins"]}
{"t":"done","summary":"Serverless REST API with Cloud-native API Gateway, Function Compute, Tablestore and OSS, paying only for actual usage."}

{"t":"say","text":"I'll draw an ACK-based Kubernetes platform with MSE for discovery, an API gateway, RocketMQ, Tair cache and PolarDB."}
{"t":"plan","products":["users","dns","alb","cloud-native-api-gateway","ack","mse","rocketmq","tair","polardb","sls"]}
{"t":"req","text":"20 Java microservices on Kubernetes"}
{"t":"assume","id":"exposure","text":"Public-facing services","alt":"Internal only via VPN"}
{"t":"assume","id":"region","text":"Singapore region","alt":"Another region"}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"Users","group":"internet","why":"Clients calling the microservices."}
{"t":"node","id":"dns","product":"dns","label":"Alibaba Cloud DNS","group":null,"why":"Resolves the API domain to the ALB."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Microservices VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"Ingress load balancer across two zones."}
{"t":"edge","id":"e-users-alb","from":"users","to":"alb","label":"HTTPS"}
{"t":"node","id":"gateway","product":"cloud-native-api-gateway","label":"API Gateway","group":"vpc","zones":["a","b"],"why":"Single entry point routing to 20 services."}
{"t":"edge","id":"e-alb-gateway","from":"alb","to":"gateway"}
{"t":"node","id":"ack","product":"ack","label":"ACK Cluster","group":"vpc","zones":["a","b"],"why":"Runs the 20 Java microservice pods."}
{"t":"edge","id":"e-gateway-ack","from":"gateway","to":"ack","label":"HTTP/gRPC"}
{"t":"node","id":"mse","product":"mse","label":"MSE Nacos","group":"vpc","zones":["a","b"],"why":"Service discovery and config for Java apps."}
{"t":"edge","id":"e-ack-mse","from":"ack","to":"mse","label":"discovery"}
{"t":"node","id":"mq","product":"rocketmq","label":"RocketMQ","group":"vpc","zones":["a","b"],"why":"Async messaging between microservices."}
{"t":"edge","id":"e-ack-mq","from":"ack","to":"mq","label":"events","kind":"async"}
{"t":"node","id":"cache","product":"tair","label":"Tair Cache","group":"vpc","zones":["a","b"],"why":"Shared cache for hot data and sessions."}
{"t":"edge","id":"e-ack-cache","from":"ack","to":"cache","label":"Redis"}
{"t":"node","id":"db","product":"polardb","label":"PolarDB","group":"vpc","zones":["a","b"],"why":"Relational database with read scaling."}
{"t":"edge","id":"e-ack-db","from":"ack","to":"db","label":"SQL"}
{"t":"node","id":"logs","product":"sls","label":"SLS","group":"sg","why":"Centralized logs and tracing for all services."}
{"t":"edge","id":"e-ack-logs","from":"ack","to":"logs","kind":"control","label":"logs"}
{"t":"ask","id":"db-engine","text":"Which relational engine do your Java services use today?","options":["MySQL","PostgreSQL","Oracle-compatible"]}
{"t":"ask","id":"messaging-pattern","text":"Do you need ordered transactional messages or standard pub/sub?","options":["Transactional (RocketMQ)","Standard pub/sub (Kafka)"]}
{"t":"done","summary":"ACK cluster with MSE Nacos, Cloud-native API Gateway, RocketMQ, Tair and PolarDB for 20 Java microservices."}

{"t":"say","text":"I'll design a highly available web shop in Singapore with ESA, ALB, WAF, ECS across two zones, Tair and RDS."}
{"t":"plan","products":["users","dns","esa","alb","waf","ecs","ess","tair","rds","oss","sls","nat"]}
{"t":"assume","id":"region","text":"Singapore for Southeast Asia shoppers","alt":"Kuala Lumpur or Jakarta"}
{"t":"assume","id":"peaks","text":"Auto Scaling handles big sales peaks","alt":"Fixed large fleet"}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"Shoppers","group":"internet","why":"30k daily users browsing the store."}
{"t":"node","id":"dns","product":"dns","label":"Cloud DNS","group":null,"why":"Resolves the store domain to ESA."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"edge","kind":"edge","label":"Edge","parent":null}
{"t":"node","id":"esa","product":"esa","label":"ESA","group":"edge","why":"Caches pages and images, accelerates dynamic traffic across SEA."}
{"t":"edge","id":"e-users-esa","from":"users","to":"esa","label":"HTTPS"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Store VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"Spreads traffic over both zones for high availability."}
{"t":"node","id":"waf","product":"waf","label":"WAF","group":"vpc","attachTo":"alb","why":"Blocks injection attacks and bots before the app."}
{"t":"edge","id":"e-esa-alb","from":"esa","to":"alb","label":"origin"}
{"t":"node","id":"app","product":"ecs","label":"App servers","group":"vpc","zones":["a","b"],"why":"Runs the store backend in two zones."}
{"t":"node","id":"scaling","product":"ess","label":"Auto Scaling","group":"vpc","attachTo":"app","why":"Scales out during big sales peaks."}
{"t":"edge","id":"e-alb-app","from":"alb","to":"app"}
{"t":"say","text":"Sessions go to Tair and orders to RDS, both deployed across two zones for resilience."}
{"t":"node","id":"cache","product":"tair","label":"Session cache","group":"vpc","zones":["a","b"],"why":"Keeps carts and sessions fast with zone redundancy."}
{"t":"node","id":"db","product":"rds","label":"Orders DB","group":"vpc","zones":["a","b"],"why":"Stores orders with a standby in the second zone."}
{"t":"edge","id":"e-app-cache","from":"app","to":"cache"}
{"t":"edge","id":"e-app-db","from":"app","to":"db","label":"SQL"}
{"t":"node","id":"media","product":"oss","label":"Product images","group":"sg","why":"Stores images that ESA serves from the edge."}
{"t":"edge","id":"e-esa-media","from":"esa","to":"media","label":"images"}
{"t":"node","id":"nat","product":"nat","label":"NAT Gateway","group":"vpc","why":"Gives app servers outbound internet for updates."}
{"t":"edge","id":"e-app-nat","from":"app","to":"nat","label":"outbound"}
{"t":"node","id":"logs","product":"sls","label":"Logs","group":"sg","why":"Central logs and alerts for troubleshooting."}
{"t":"edge","id":"e-app-logs","from":"app","to":"logs","kind":"control"}
{"t":"ask","id":"db-engine","text":"Which database engine do you prefer?","options":["MySQL","PostgreSQL"]}
{"t":"ask","id":"peak-scale","text":"How many instances do you expect at peak?","options":["Under 20","20 to 50","Over 50"]}
{"t":"done","summary":"Highly available SEA web store in Singapore: ESA, ALB with WAF, ECS across two zones with Auto Scaling, Tair, RDS, OSS and SLS."}

{"t":"say","text":"I'll draw an internal RAG assistant using Qwen models, where employees query policy docs and wiki content from your VPC."}
{"t":"plan","products":["users","alb","ecs","model-studio","elasticsearch","oss","nat","sls"]}
{"t":"assume","id":"scale","text":"About 500 internal employees","alt":"Over 5,000 employees"}
{"t":"assume","id":"region","text":"Singapore region","alt":"Another region"}
{"t":"group","id":"internal","kind":"external","label":"Internal users","parent":null}
{"t":"node","id":"users","product":"users","label":"Employees","group":"internal","why":"Staff asking questions about policies and wiki."}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Internal VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"Routes internal traffic to the assistant backend."}
{"t":"edge","id":"e-users-alb","from":"users","to":"alb","label":"HTTPS"}
{"t":"node","id":"app","product":"ecs","label":"RAG assistant","group":"vpc","zones":["a","b"],"why":"Runs retrieval and generation logic for employee queries."}
{"t":"edge","id":"e-alb-app","from":"alb","to":"app"}
{"t":"node","id":"vector","product":"elasticsearch","label":"Vector store","group":"vpc","zones":["a","b"],"why":"Stores embeddings of policy documents and wiki pages."}
{"t":"edge","id":"e-app-vector","from":"app","to":"vector","label":"search"}
{"t":"node","id":"docs","product":"oss","label":"Source documents","group":"sg","why":"Holds raw policy PDFs and wiki exports for ingestion."}
{"t":"edge","id":"e-app-docs","from":"app","to":"docs","label":"read"}
{"t":"node","id":"nat","product":"nat","label":"NAT Gateway","group":"vpc","why":"Lets the app reach Model Studio APIs over the internet."}
{"t":"edge","id":"e-app-nat","from":"app","to":"nat","label":"outbound"}
{"t":"node","id":"llm","product":"model-studio","label":"Model Studio","group":"sg","why":"Hosted Qwen models generate answers from retrieved context."}
{"t":"edge","id":"e-nat-llm","from":"nat","to":"llm","label":"API"}
{"t":"node","id":"logs","product":"sls","label":"Logs","group":"sg","why":"Captures queries and responses for auditing."}
{"t":"edge","id":"e-app-logs","from":"app","to":"logs","kind":"control"}
{"t":"ask","id":"wiki-source","text":"Where is your wiki currently hosted?","options":["Confluence or Notion","Internal database","Static files in OSS"]}
{"t":"ask","id":"auth-method","text":"How should employees authenticate to the assistant?","options":["SSO via IDaaS","Existing corporate SSO","No auth yet"]}
{"t":"done","summary":"Internal RAG assistant on ECS with Elasticsearch vector store, calling hosted Qwen via NAT, and source docs in OSS."}

{"t":"say","text":"I'll draw a data platform that replicates MySQL in real time via DTS, runs nightly batch in MaxCompute, and serves dashboards."}
{"t":"plan","products":["rds","dts","dataworks","maxcompute","hologres","quick-bi","sls"]}
{"t":"assume","id":"source-db","text":"Source is an existing RDS MySQL order database","alt":"On-premises MySQL"}
{"t":"assume","id":"region","text":"Platform runs in Singapore","alt":"Another region"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Data Platform VPC","parent":"sg"}
{"t":"node","id":"rds","product":"rds","label":"Order DB (MySQL)","group":"vpc","zones":["a","b"],"why":"Source of truth for order transactions."}
{"t":"node","id":"dts","product":"dts","label":"DTS Sync","group":"sg","why":"Replicates MySQL changes to the warehouse in real time."}
{"t":"edge","id":"e-rds-dts","from":"rds","to":"dts","label":"CDC","kind":"data"}
{"t":"node","id":"maxcompute","product":"maxcompute","label":"MaxCompute Warehouse","group":"sg","why":"Stores historical order data for nightly batch analytics."}
{"t":"edge","id":"e-dts-maxcompute","from":"dts","to":"maxcompute","label":"sync","kind":"data"}
{"t":"node","id":"dataworks","product":"dataworks","label":"DataWorks Scheduler","group":"sg","why":"Orchestrates nightly ETL jobs over MaxCompute tables."}
{"t":"edge","id":"e-dataworks-maxcompute","from":"dataworks","to":"maxcompute","label":"nightly ETL","kind":"control"}
{"t":"node","id":"hologres","product":"hologres","label":"Hologres Serving","group":"vpc","zones":["a","b"],"why":"Serves processed data with sub-second queries for dashboards."}
{"t":"edge","id":"e-maxcompute-hologres","from":"maxcompute","to":"hologres","label":"load","kind":"data"}
{"t":"node","id":"quickbi","product":"quick-bi","label":"Quick BI Dashboards","group":"sg","why":"Gives business users self-service reports and visualizations."}
{"t":"edge","id":"e-hologres-quickbi","from":"hologres","to":"quickbi","label":"queries","kind":"data"}
{"t":"node","id":"sls","product":"sls","label":"Log Service","group":"sg","why":"Collects pipeline logs and monitors job health."}
{"t":"edge","id":"e-dataworks-sls","from":"dataworks","to":"sls","kind":"control"}
{"t":"ask","id":"source-location","text":"Where does your source MySQL currently run?","options":["Alibaba Cloud RDS","On-premises","Another cloud provider"]}
{"t":"ask","id":"latency","text":"Do dashboards need real-time data or is nightly refresh enough?","options":["Real-time via DTS","Nightly batch only"]}
{"t":"done","summary":"Data platform with DTS real-time replication from MySQL, MaxCompute batch warehouse, Hologres serving layer and Quick BI dashboards."}

{"t":"say","text":"I'll draw an IoT telemetry pipeline: devices publish to IoT Platform, Flink detects anomalies in real time, and DataV powers the live dashboard."}
{"t":"plan","products":["iot-devices","iot-platform","kafka","flink","tablestore","hologres","datav","sls"]}
{"t":"assume","id":"region","text":"Singapore region","alt":"Another international region"}
{"t":"assume","id":"protocol","text":"Devices use MQTT over IoT Platform","alt":"Direct Kafka ingestion via edge gateway"}
{"t":"group","id":"field","kind":"external","label":"Field","parent":null}
{"t":"node","id":"devices","product":"iot-devices","label":"100k IoT devices","group":"field","why":"Publish telemetry every few seconds."}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Telemetry VPC","parent":"sg"}
{"t":"node","id":"iot","product":"iot-platform","label":"IoT Platform","group":"sg","why":"Ingests and routes device telemetry via rules engine."}
{"t":"edge","id":"e-devices-iot","from":"devices","to":"iot","label":"MQTT","kind":"data"}
{"t":"node","id":"kafka","product":"kafka","label":"Kafka","group":"vpc","zones":["a","b"],"why":"Buffers high-throughput telemetry for stream processing."}
{"t":"edge","id":"e-iot-kafka","from":"iot","to":"kafka","label":"rules","kind":"async"}
{"t":"node","id":"flink","product":"flink","label":"Flink","group":"vpc","why":"Runs real-time anomaly detection on telemetry streams."}
{"t":"edge","id":"e-kafka-flink","from":"kafka","to":"flink","label":"stream","kind":"data"}
{"t":"node","id":"alerts","product":"tablestore","label":"Alert store","group":"sg","why":"Stores detected anomalies for alerting and history."}
{"t":"edge","id":"e-flink-alerts","from":"flink","to":"alerts","label":"anomalies","kind":"data"}
{"t":"node","id":"warehouse","product":"hologres","label":"Hologres","group":"vpc","why":"Serves aggregated metrics for the live dashboard."}
{"t":"edge","id":"e-flink-warehouse","from":"flink","to":"warehouse","label":"metrics","kind":"data"}
{"t":"node","id":"dashboard","product":"datav","label":"Live dashboard","group":"sg","why":"Visualizes real-time metrics and anomaly alerts."}
{"t":"edge","id":"e-warehouse-dashboard","from":"warehouse","to":"dashboard","label":"query","kind":"data"}
{"t":"edge","id":"e-alerts-dashboard","from":"alerts","to":"dashboard","label":"alerts","kind":"data"}
{"t":"node","id":"logs","product":"sls","label":"Logs","group":"sg","why":"Collects pipeline logs and supports alerting rules."}
{"t":"edge","id":"e-flink-logs","from":"flink","to":"logs","kind":"control"}
{"t":"ask","id":"alert-channel","text":"How should anomaly alerts be delivered to your team?","options":["SMS or email","Webhook to IM app","Both"]}
{"t":"ask","id":"retention","text":"How long must raw telemetry be retained?","options":["7 days hot only","30 days in OSS","Over 90 days in OSS"]}
{"t":"done","summary":"IoT Platform ingests 100k device streams into Kafka, Flink detects anomalies in real time, Tablestore stores alerts, Hologres serves metrics, and DataV renders the live dashboard."}

{"t":"say","text":"I'll draw your on-premises data center connected to Alibaba Cloud Singapore via Express Connect, with a migration path for your VMs."}
{"t":"plan","products":["onprem-dc","express-connect","vpc","ecs","smc","dts","nat","sls"]}
{"t":"assume","id":"migration-traffic","text":"Moderate migration traffic fits Express Connect","alt":"Large steady traffic needs dedicated line sizing"}
{"t":"group","id":"onprem","kind":"onprem","label":"On-premises Singapore","parent":null}
{"t":"node","id":"onprem-dc","product":"onprem-dc","label":"On-prem DC","group":"onprem","why":"Your existing data center hosting VMs to migrate."}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Cloud VPC","parent":"sg"}
{"t":"node","id":"express","product":"express-connect","label":"Express Connect","group":"vpc","why":"Private dedicated link between on-prem and cloud VPC."}
{"t":"edge","id":"e-onprem-express","from":"onprem-dc","to":"express","label":"private link"}
{"t":"node","id":"app","product":"ecs","label":"Migrated VMs","group":"vpc","zones":["a","b"],"why":"Target ECS instances receiving migrated workloads."}
{"t":"edge","id":"e-express-app","from":"express","to":"app","label":"VPC traffic"}
{"t":"node","id":"smc","product":"smc","label":"Server Migration Center","group":"sg","why":"Incrementally migrates on-prem VMs to ECS."}
{"t":"edge","id":"e-onprem-smc","from":"onprem-dc","to":"smc","label":"migrate","kind":"control"}
{"t":"edge","id":"e-smc-app","from":"smc","to":"app","label":"deploy","kind":"control"}
{"t":"node","id":"dts","product":"dts","label":"DTS","group":"sg","why":"Syncs databases from on-prem to cloud during cutover."}
{"t":"edge","id":"e-onprem-dts","from":"onprem-dc","to":"dts","label":"db sync","kind":"data"}
{"t":"node","id":"nat","product":"nat","label":"NAT Gateway","group":"vpc","why":"Outbound internet for migrated VMs after cutover."}
{"t":"edge","id":"e-app-nat","from":"app","to":"nat","label":"outbound"}
{"t":"node","id":"logs","product":"sls","label":"Log Service","group":"sg","why":"Centralizes migration and runtime logs."}
{"t":"edge","id":"e-app-logs","from":"app","to":"logs","kind":"control"}
{"t":"ask","id":"db-type","text":"What databases run on your on-prem VMs?","options":["MySQL or PostgreSQL","SQL Server","No database migration needed"]}
{"t":"ask","id":"vm-count","text":"Roughly how many VMs are you migrating?","options":["Under 20","20 to 100","Over 100"]}
{"t":"done","summary":"On-prem Singapore DC linked to Alibaba Cloud VPC via Express Connect, with SMC for VM migration and DTS for database sync."}

{"t":"say","text":"I'll design a live-streaming and VOD platform for e-sports fans using ApsaraVideo Live, VOD, ESA for delivery, and OSS for storage."}
{"t":"plan","products":["users","dns","esa","alb","waf","live","vod","mps","oss","ecs","rds","tair","sls"]}
{"t":"assume","id":"scale","text":"About 50k concurrent viewers","alt":"Over 500k concurrent viewers"}
{"t":"assume","id":"region","text":"Global audience, origin in Singapore","alt":"Regional audience only"}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"E-sports fans","group":"internet","why":"Viewers watching live streams and VOD content."}
{"t":"node","id":"dns","product":"dns","label":"Cloud DNS","group":null,"why":"Resolves platform domains to ESA edge."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"edge","kind":"edge","label":"Edge","parent":null}
{"t":"node","id":"esa","product":"esa","label":"ESA","group":"edge","why":"Accelerates live and VOD playback globally with caching and DDoS protection."}
{"t":"edge","id":"e-users-esa","from":"users","to":"esa","label":"HTTPS"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Platform VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"Routes API and web traffic across zones."}
{"t":"node","id":"waf","product":"waf","label":"WAF","group":"vpc","attachTo":"alb","why":"Protects the platform APIs from attacks and bots."}
{"t":"edge","id":"e-esa-alb","from":"esa","to":"alb","label":"origin"}
{"t":"node","id":"app","product":"ecs","label":"App servers","group":"vpc","zones":["a","b"],"why":"Runs the e-sports platform backend and APIs."}
{"t":"edge","id":"e-alb-app","from":"alb","to":"app"}
{"t":"say","text":"Now adding the media pipeline: Live ingest, VOD, transcoding and object storage."}
{"t":"node","id":"live","product":"live","label":"ApsaraVideo Live","group":"sg","why":"Ingests, transcodes and distributes live e-sports streams."}
{"t":"edge","id":"e-esa-live","from":"esa","to":"live","label":"pull"}
{"t":"node","id":"vod","product":"vod","label":"ApsaraVideo VOD","group":"sg","why":"Stores and delivers recorded matches as VOD."}
{"t":"edge","id":"e-esa-vod","from":"esa","to":"vod","label":"pull"}
{"t":"node","id":"mps","product":"mps","label":"Media Processing","group":"sg","why":"Transcodes and adds overlays to live and VOD content."}
{"t":"edge","id":"e-live-mps","from":"live","to":"mps","label":"transcode"}
{"t":"edge","id":"e-vod-mps","from":"vod","to":"mps","label":"transcode"}
{"t":"node","id":"media","product":"oss","label":"Media storage","group":"sg","why":"Stores raw and transcoded video files durably."}
{"t":"edge","id":"e-mps-media","from":"mps","to":"media","label":"output"}
{"t":"edge","id":"e-live-media","from":"live","to":"media","label":"record"}
{"t":"say","text":"Adding cache, database and logging for the platform backend."}
{"t":"node","id":"cache","product":"tair","label":"Session cache","group":"vpc","zones":["a","b"],"why":"Caches user sessions and stream metadata for low latency."}
{"t":"node","id":"db","product":"rds","label":"Platform DB","group":"vpc","zones":["a","b"],"why":"Stores users, teams, schedules and VOD metadata."}
{"t":"edge","id":"e-app-cache","from":"app","to":"cache"}
{"t":"edge","id":"e-app-db","from":"app","to":"db","label":"SQL"}
{"t":"node","id":"logs","product":"sls","label":"Logs","group":"sg","why":"Collects platform and streaming logs for monitoring."}
{"t":"edge","id":"e-app-logs","from":"app","to":"logs","kind":"control"}
{"t":"edge","id":"e-live-logs","from":"live","to":"logs","kind":"control"}
{"t":"ask","id":"ingest-source","text":"How will streamers ingest live e-sports matches?","options":["RTMP push from OBS","SDK in custom app","Both"]}
{"t":"ask","id":"interactive-features","text":"Do you need real-time chat or interactive features during streams?","options":["Yes, live chat needed","No, just video"]}
{"t":"done","summary":"Live-streaming and VOD platform with ESA delivery, ApsaraVideo Live and VOD, MPS transcoding, OSS storage, and an ECS backend on ALB."}

{"t":"say","text":"I'll draw a secure multi-account landing zone with central identity, audit logging, threat detection and network firewalls."}
{"t":"plan","products":["acgc","resource-management","cloudsso","ram","idaas","actiontrail","sls","security-center","cloud-firewall","cloud-config","advisor"]}
{"t":"assume","id":"accounts","text":"New multi-account setup via Resource Directory","alt":"Existing accounts to enroll"}
{"t":"group","id":"governance","kind":"external","label":"Governance & Identity","parent":null}
{"t":"node","id":"acgc","product":"acgc","label":"Agentic Cloud Governance Center","group":"governance","why":"Automates landing zone setup and governance baseline."}
